insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000006', '00000000-0000-4000-8000-00000000c0de', 'Alışveriş', 'public', '[{"id": "a1-shop", "word": "shop", "pos": "n", "level": "A1", "tr": ["mağaza", "dükkân"], "example_en": "This shop has nice shoes.", "example_tr": "Bu mağazada güzel ayakkabılar var.", "note": "Amerikan İngilizcesinde mağaza için daha çok ''store'' denir.", "senses": [{"pos": "v", "tr": ["alışveriş yapmak"], "example_en": "I like to shop here.", "example_tr": "Burada alışveriş yapmayı severim."}]}, {"id": "a1-market", "word": "market", "pos": "n", "level": "A1", "tr": ["pazar", "çarşı"], "example_en": "The market is very big.", "example_tr": "Pazar çok büyük.", "note": "Türkçedeki ''market'' (bakkal/süpermarket) için İngilizcede ''supermarket'' veya ''grocery store'' denir."}, {"id": "a1-buy", "word": "buy", "pos": "v", "level": "A1", "tr": ["satın almak", "almak"], "example_en": "I want to buy a new bag.", "example_tr": "Yeni bir çanta almak istiyorum."}, {"id": "a1-sell", "word": "sell", "pos": "v", "level": "A1", "tr": ["satmak"], "example_en": "Do you sell shoes here?", "example_tr": "Burada ayakkabı satıyor musunuz?"}, {"id": "a1-price", "word": "price", "pos": "n", "level": "A1", "tr": ["fiyat"], "example_en": "The price is very good.", "example_tr": "Fiyatı çok iyi."}, {"id": "a1-money", "word": "money", "pos": "n", "level": "A1", "tr": ["para"], "example_en": "I don''t have much money.", "example_tr": "Çok param yok.", "note": "''Money'' sayılamaz; çoğul yapılmaz ve ''many'' yerine ''much'' ile kullanılır."}, {"id": "a1-cheap", "word": "cheap", "pos": "adj", "level": "A1", "tr": ["ucuz"], "example_en": "These shirts are very cheap.", "example_tr": "Bu gömlekler çok ucuz."}, {"id": "a1-expensive", "word": "expensive", "pos": "adj", "level": "A1", "tr": ["pahalı"], "example_en": "This dress is too expensive.", "example_tr": "Bu elbise fazla pahalı."}, {"id": "a1-colour", "word": "colour", "pos": "n", "level": "A1", "tr": ["renk"], "example_en": "What colour do you like?", "example_tr": "Hangi rengi seversin?", "note": "Amerikan İngilizcesinde ''color'' şeklinde yazılır."}, {"id": "a1-size", "word": "size", "pos": "n", "level": "A1", "tr": ["beden", "numara", "boyut"], "example_en": "What is your size?", "example_tr": "Bedeniniz nedir?", "note": "Kıyafet için ''beden'', ayakkabı için ''numara'' anlamında kullanılır."}, {"id": "a1-shirt", "word": "shirt", "pos": "n", "level": "A1", "tr": ["gömlek"], "example_en": "He needs a white shirt.", "example_tr": "Beyaz bir gömleğe ihtiyacı var.", "note": "Tişört için ''T-shirt'' denir."}, {"id": "a1-shoes", "word": "shoes", "pos": "n", "level": "A1", "tr": ["ayakkabı"], "example_en": "I like your new shoes.", "example_tr": "Yeni ayakkabılarını beğendim.", "note": "Tek bir teki için ''shoe'' denir ama genelde çift olduğu için çoğul (''shoes'') kullanılır."}, {"id": "a1-dress", "word": "dress", "pos": "n", "level": "A1", "tr": ["elbise"], "example_en": "She wants a red dress.", "example_tr": "Kırmızı bir elbise istiyor."}, {"id": "a1-bag", "word": "bag", "pos": "n", "level": "A1", "tr": ["çanta", "poşet"], "example_en": "Do you need a bag?", "example_tr": "Poşet ister misiniz?", "note": "Hem kol/sırt çantası hem de alışveriş poşeti için kullanılır."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000007', '00000000-0000-4000-8000-00000000c0de', 'Kafede', 'public', '[{"id": "a1-café", "word": "café", "pos": "n", "level": "A1", "tr": ["kafe"], "example_en": "This café is very nice.", "example_tr": "Bu kafe çok hoş."}, {"id": "a1-coffee", "word": "coffee", "pos": "n", "level": "A1", "tr": ["kahve"], "example_en": "I''d like a coffee, please.", "example_tr": "Bir kahve alayım, lütfen."}, {"id": "a1-tea", "word": "tea", "pos": "n", "level": "A1", "tr": ["çay"], "example_en": "Do you want tea?", "example_tr": "Çay ister misin?"}, {"id": "a1-water", "word": "water", "pos": "n", "level": "A1", "tr": ["su"], "example_en": "Can I have some water?", "example_tr": "Biraz su alabilir miyim?"}, {"id": "a1-milk", "word": "milk", "pos": "n", "level": "A1", "tr": ["süt"], "example_en": "I like coffee with milk.", "example_tr": "Sütlü kahveyi severim."}, {"id": "a1-sugar", "word": "sugar", "pos": "n", "level": "A1", "tr": ["şeker"], "example_en": "No sugar, please.", "example_tr": "Şekersiz olsun, lütfen."}, {"id": "a1-cake", "word": "cake", "pos": "n", "level": "A1", "tr": ["kek", "pasta"], "example_en": "This cake is very good.", "example_tr": "Bu kek çok güzel."}, {"id": "a1-sandwich", "word": "sandwich", "pos": "n", "level": "A1", "tr": ["sandviç"], "example_en": "I want a big sandwich.", "example_tr": "Büyük bir sandviç istiyorum."}, {"id": "a1-menu", "word": "menu", "pos": "n", "level": "A1", "tr": ["menü"], "example_en": "Can I see the menu?", "example_tr": "Menüye bakabilir miyim?"}, {"id": "a1-bill", "word": "bill", "pos": "n", "level": "A1", "tr": ["hesap"], "example_en": "The bill, please.", "example_tr": "Hesap, lütfen.", "note": "Amerikan İngilizcesinde restoranda ''check'' denir."}, {"id": "a1-cup", "word": "cup", "pos": "n", "level": "A1", "tr": ["fincan"], "example_en": "A cup of coffee, please.", "example_tr": "Bir fincan kahve, lütfen."}, {"id": "a1-glass", "word": "glass", "pos": "n", "level": "A1", "tr": ["bardak"], "example_en": "A glass of water, please.", "example_tr": "Bir bardak su, lütfen.", "note": "''glass'' cam anlamına da gelir."}, {"id": "a1-table", "word": "table", "pos": "n", "level": "A1", "tr": ["masa"], "example_en": "We sit at a small table.", "example_tr": "Küçük bir masaya oturuyoruz."}, {"id": "a1-card", "word": "card", "pos": "n", "level": "A1", "tr": ["kart"], "example_en": "Can I pay by card?", "example_tr": "Kartla ödeyebilir miyim?"}]'::jsonb)
