insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000008', '00000000-0000-4000-8000-00000000c0de', 'Şehirde yol bulma', 'public', '[{"id": "a1-city", "word": "city", "pos": "n", "level": "A1", "tr": ["şehir", "kent"], "example_en": "Ankara is a big city.", "example_tr": "Ankara büyük bir şehir.", "note": "Çoğul hali: ''cities''."}, {"id": "a1-street", "word": "street", "pos": "n", "level": "A1", "tr": ["sokak", "cadde"], "example_en": "Our hotel is on this street.", "example_tr": "Otelimiz bu sokakta."}, {"id": "a1-station", "word": "station", "pos": "n", "level": "A1", "tr": ["istasyon", "gar"], "example_en": "Where is the train station?", "example_tr": "Tren istasyonu nerede?"}, {"id": "a1-bus", "word": "bus", "pos": "n", "level": "A1", "tr": ["otobüs"], "example_en": "I go to work by bus.", "example_tr": "İşe otobüsle gidiyorum.", "note": "''Otobüsle'' derken ''by bus'' kullanılır."}, {"id": "a1-train", "word": "train", "pos": "n", "level": "A1", "tr": ["tren"], "example_en": "The train to London is here.", "example_tr": "Londra treni burada."}, {"id": "a1-taxi", "word": "taxi", "pos": "n", "level": "A1", "tr": ["taksi"], "example_en": "Let''s go to the hotel by taxi.", "example_tr": "Otele taksiyle gidelim."}, {"id": "a1-car", "word": "car", "pos": "n", "level": "A1", "tr": ["araba"], "example_en": "They have a small car.", "example_tr": "Küçük bir arabaları var."}, {"id": "a1-airport", "word": "airport", "pos": "n", "level": "A1", "tr": ["havaalanı", "havalimanı"], "example_en": "Is the airport far from here?", "example_tr": "Havaalanı buradan uzak mı?"}, {"id": "a1-hotel", "word": "hotel", "pos": "n", "level": "A1", "tr": ["otel"], "example_en": "This is a very good hotel.", "example_tr": "Burası çok iyi bir otel."}, {"id": "a1-bank", "word": "bank", "pos": "n", "level": "A1", "tr": ["banka"], "example_en": "My friend works at a bank.", "example_tr": "Arkadaşım bir bankada çalışıyor."}, {"id": "a1-hospital", "word": "hospital", "pos": "n", "level": "A1", "tr": ["hastane"], "example_en": "Is there a hospital near here?", "example_tr": "Buralarda hastane var mı?"}, {"id": "a1-park", "word": "park", "pos": "n", "level": "A1", "tr": ["park"], "example_en": "The children are in the park.", "example_tr": "Çocuklar parkta."}, {"id": "a1-map", "word": "map", "pos": "n", "level": "A1", "tr": ["harita"], "example_en": "Do you have a city map?", "example_tr": "Şehir haritanız var mı?"}, {"id": "a1-left", "word": "left", "pos": "adv", "level": "A1", "tr": ["sola", "solda"], "example_en": "Turn left at the bank.", "example_tr": "Bankadan sola dönün.", "note": "''Solda'' derken ''on the left'' kullanılır.", "senses": [{"pos": "n", "tr": ["sol"], "example_en": "The hotel is on your left.", "example_tr": "Otel solunuzda."}]}]'::jsonb)
