insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000009', '00000000-0000-4000-8000-00000000c0de', 'Sağlık ve doktor', 'public', '[{"id": "a2-body", "word": "body", "pos": "n", "level": "A2", "tr": ["vücut", "beden"], "example_en": "Exercise is good for your body.", "example_tr": "Egzersiz vücuduna iyi gelir."}, {"id": "a2-arm", "word": "arm", "pos": "n", "level": "A2", "tr": ["kol"], "example_en": "My left arm hurts.", "example_tr": "Sol kolum ağrıyor."}, {"id": "a2-leg", "word": "leg", "pos": "n", "level": "A2", "tr": ["bacak"], "example_en": "He can''t walk on this leg.", "example_tr": "Bu bacağının üstüne basamıyor."}, {"id": "a2-back", "word": "back", "pos": "n", "level": "A2", "tr": ["sırt", "bel"], "example_en": "My back hurts today.", "example_tr": "Bugün sırtım ağrıyor.", "note": "''Geri'' ve ''arka'' anlamı da vardır."}, {"id": "a2-stomach", "word": "stomach", "pos": "n", "level": "A2", "tr": ["mide", "karın"], "example_en": "My stomach hurts after dinner.", "example_tr": "Akşam yemeğinden sonra midem ağrıyor.", "note": "''ch'' harfi ''k'' gibi okunur: stamık."}, {"id": "a2-tooth", "word": "tooth", "pos": "n", "level": "A2", "tr": ["diş"], "example_en": "This tooth hurts a lot.", "example_tr": "Bu dişim çok ağrıyor.", "note": "Çoğulu düzensizdir: ''teeth''."}, {"id": "a2-eye", "word": "eye", "pos": "n", "level": "A2", "tr": ["göz"], "example_en": "My eyes are very tired.", "example_tr": "Gözlerim çok yorgun."}, {"id": "a2-ear", "word": "ear", "pos": "n", "level": "A2", "tr": ["kulak"], "example_en": "I have a pain in my ear.", "example_tr": "Kulağımda bir ağrı var."}, {"id": "a2-pain", "word": "pain", "pos": "n", "level": "A2", "tr": ["ağrı", "acı"], "example_en": "Do you feel any pain?", "example_tr": "Hiç ağrı hissediyor musun?"}, {"id": "a2-hurt", "word": "hurt", "pos": "v", "level": "A2", "tr": ["ağrımak", "acımak"], "example_en": "Does your leg hurt?", "example_tr": "Bacağın ağrıyor mu?", "note": "Geçmiş zaman hali de ''hurt'' şeklindedir."}, {"id": "a2-cough", "word": "cough", "pos": "v", "level": "A2", "tr": ["öksürmek"], "example_en": "He coughs at night.", "example_tr": "Geceleri öksürüyor.", "note": "''kof'' gibi okunur.", "senses": [{"pos": "n", "tr": ["öksürük"], "example_en": "I have a bad cough.", "example_tr": "Kötü bir öksürüğüm var."}]}, {"id": "a2-fever", "word": "fever", "pos": "n", "level": "A2", "tr": ["ateş"], "example_en": "The child has a fever.", "example_tr": "Çocuğun ateşi var.", "note": "Hastalık ateşi için kullanılır."}, {"id": "a2-headache", "word": "headache", "pos": "n", "level": "A2", "tr": ["baş ağrısı"], "example_en": "I have a bad headache.", "example_tr": "Kötü bir baş ağrım var."}, {"id": "a2-appointment", "word": "appointment", "pos": "n", "level": "A2", "tr": ["randevu"], "example_en": "I have an appointment at ten.", "example_tr": "Saat onda randevum var.", "note": "Doktor ve iş randevuları için kullanılır."}]'::jsonb)
