insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000010', '00000000-0000-4000-8000-00000000c0de', 'Teknoloji', 'public', '[{"id": "a2-phone", "word": "phone", "pos": "n", "level": "A2", "tr": ["telefon"], "example_en": "Where is my phone?", "example_tr": "Telefonum nerede?", "senses": [{"pos": "v", "tr": ["telefon etmek", "aramak"], "example_en": "I will phone you tomorrow.", "example_tr": "Seni yarın arayacağım."}]}, {"id": "a2-message", "word": "message", "pos": "n", "level": "A2", "tr": ["mesaj"], "example_en": "I have a new message.", "example_tr": "Yeni bir mesajım var.", "senses": [{"pos": "v", "tr": ["mesaj atmak"], "example_en": "Message me when you leave.", "example_tr": "Çıkınca bana mesaj at."}]}, {"id": "a2-call", "word": "call", "pos": "v", "level": "A2", "tr": ["aramak"], "example_en": "Can I call you now?", "example_tr": "Seni şimdi arayabilir miyim?", "senses": [{"pos": "n", "tr": ["arama", "çağrı"], "example_en": "Thanks for your call.", "example_tr": "Aradığın için teşekkürler."}]}, {"id": "a2-text", "word": "text", "pos": "v", "level": "A2", "tr": ["mesaj atmak"], "example_en": "Text me when you get home.", "example_tr": "Eve varınca bana mesaj at.", "senses": [{"pos": "n", "tr": ["kısa mesaj", "metin"], "example_en": "I read your text.", "example_tr": "Mesajını okudum."}]}, {"id": "a2-website", "word": "website", "pos": "n", "level": "A2", "tr": ["web sitesi", "internet sitesi"], "example_en": "This website is very good.", "example_tr": "Bu internet sitesi çok güzel."}, {"id": "a2-app", "word": "app", "pos": "n", "level": "A2", "tr": ["uygulama"], "example_en": "Try this new app.", "example_tr": "Bu yeni uygulamayı dene.", "note": "''application'' sözcüğünün kısaltmasıdır."}, {"id": "a2-password", "word": "password", "pos": "n", "level": "A2", "tr": ["şifre", "parola"], "example_en": "I forgot my password.", "example_tr": "Şifremi unuttum."}, {"id": "a2-download", "word": "download", "pos": "v", "level": "A2", "tr": ["indirmek"], "example_en": "Download the app now.", "example_tr": "Uygulamayı şimdi indir."}, {"id": "a2-online", "word": "online", "pos": "adj", "level": "A2", "tr": ["çevrim içi"], "example_en": "Is the shop online?", "example_tr": "Dükkan çevrim içi mi?", "senses": [{"pos": "adv", "tr": ["internetten", "çevrim içi"], "example_en": "I buy books online.", "example_tr": "Kitapları internetten alırım."}]}, {"id": "a2-screen", "word": "screen", "pos": "n", "level": "A2", "tr": ["ekran"], "example_en": "Look at the screen.", "example_tr": "Ekrana bak."}, {"id": "a2-battery", "word": "battery", "pos": "n", "level": "A2", "tr": ["pil", "batarya"], "example_en": "My battery is almost dead.", "example_tr": "Şarjım bitmek üzere.", "note": "Telefon şarjı için ''battery'' denir."}, {"id": "a2-charge", "word": "charge", "pos": "v", "level": "A2", "tr": ["şarj etmek"], "example_en": "I must charge my phone.", "example_tr": "Telefonumu şarj etmeliyim."}, {"id": "a2-camera", "word": "camera", "pos": "n", "level": "A2", "tr": ["kamera", "fotoğraf makinesi"], "example_en": "The camera takes good photos.", "example_tr": "Kamera güzel fotoğraflar çeker."}, {"id": "a2-video", "word": "video", "pos": "n", "level": "A2", "tr": ["video"], "example_en": "Let''s watch a video.", "example_tr": "Bir video izleyelim."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000011', '00000000-0000-4000-8000-00000000c0de', 'Doğa ve hava', 'public', '[{"id": "a2-season", "word": "season", "pos": "n", "level": "A2", "tr": ["mevsim"], "example_en": "Summer is a hot season.", "example_tr": "Yaz sıcak bir mevsimdir."}, {"id": "a2-spring", "word": "spring", "pos": "n", "level": "A2", "tr": ["ilkbahar", "bahar"], "example_en": "I love walking in the spring.", "example_tr": "İlkbaharda yürümeyi çok severim."}, {"id": "a2-summer", "word": "summer", "pos": "n", "level": "A2", "tr": ["yaz"], "example_en": "We visit the sea every summer.", "example_tr": "Her yaz denize gideriz."}, {"id": "a2-autumn", "word": "autumn", "pos": "n", "level": "A2", "tr": ["sonbahar", "güz"], "example_en": "It rains a lot in autumn.", "example_tr": "Sonbaharda çok yağmur yağar.", "note": "Amerikan İngilizcesinde ''fall'' denir."}, {"id": "a2-winter", "word": "winter", "pos": "n", "level": "A2", "tr": ["kış"], "example_en": "Winter is very cold here.", "example_tr": "Burada kış çok soğuktur."}, {"id": "a2-sunny", "word": "sunny", "pos": "adj", "level": "A2", "tr": ["güneşli"], "example_en": "Today is sunny and warm.", "example_tr": "Bugün güneşli ve ılık."}, {"id": "a2-cloudy", "word": "cloudy", "pos": "adj", "level": "A2", "tr": ["bulutlu"], "example_en": "The morning was cloudy.", "example_tr": "Sabah bulutluydu."}, {"id": "a2-windy", "word": "windy", "pos": "adj", "level": "A2", "tr": ["rüzgarlı"], "example_en": "It is windy near the river.", "example_tr": "Nehrin yanında rüzgar var."}, {"id": "a2-storm", "word": "storm", "pos": "n", "level": "A2", "tr": ["fırtına"], "example_en": "A big storm is coming this evening.", "example_tr": "Bu akşam büyük bir fırtına geliyor."}, {"id": "a2-temperature", "word": "temperature", "pos": "n", "level": "A2", "tr": ["sıcaklık", "hava sıcaklığı"], "example_en": "The temperature is thirty today.", "example_tr": "Sıcaklık bugün otuz derece."}, {"id": "a2-degree", "word": "degree", "pos": "n", "level": "A2", "tr": ["derece"], "example_en": "It is only five degrees outside.", "example_tr": "Dışarısı sadece beş derece."}, {"id": "a2-countryside", "word": "countryside", "pos": "n", "level": "A2", "tr": ["kırsal", "köy ortamı"], "example_en": "I want to live in the countryside.", "example_tr": "Kırsalda yaşamak istiyorum."}, {"id": "a2-mountain", "word": "mountain", "pos": "n", "level": "A2", "tr": ["dağ"], "example_en": "We can see the tall mountain.", "example_tr": "Yüksek dağı görebiliyoruz."}, {"id": "a2-river", "word": "river", "pos": "n", "level": "A2", "tr": ["nehir", "ırmak"], "example_en": "Children swim in the river.", "example_tr": "Çocuklar nehirde yüzüyor."}]'::jsonb)
