insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000012', '00000000-0000-4000-8000-00000000c0de', 'Para ve bütçe', 'public', '[{"id": "b1-afford", "word": "afford", "pos": "v", "level": "B1", "tr": ["parası yetmek", "gücü yetmek"], "example_en": "I can''t afford a new car.", "example_tr": "Yeni bir araba almaya gücüm yetmez.", "note": "Genellikle ''can'', ''could'' veya ''be able to'' ile kullanılır."}, {"id": "b1-budget", "word": "budget", "pos": "n", "level": "B1", "tr": ["bütçe"], "example_en": "My budget is very small.", "example_tr": "Bütçem çok dar.", "senses": [{"pos": "v", "tr": ["bütçe yapmak"], "example_en": "We need to budget our money.", "example_tr": "Bütçe yapmamız lazım."}]}, {"id": "b1-save", "word": "save", "pos": "v", "level": "B1", "tr": ["biriktirmek", "tasarruf etmek"], "example_en": "I want to save money for a holiday.", "example_tr": "Tatil için para biriktirmek istiyorum."}, {"id": "b1-spend", "word": "spend", "pos": "v", "level": "B1", "tr": ["harcamak"], "example_en": "Don''t spend all your money today.", "example_tr": "Bugün bütün paranı harcama.", "note": "Zaman harcamak/geçirmek anlamı da vardır."}, {"id": "b1-bargain", "word": "bargain", "pos": "n", "level": "B1", "tr": ["kelepir", "ucuz mal"], "example_en": "This shirt is a great bargain.", "example_tr": "Bu gömlek tam kelepir.", "senses": [{"pos": "v", "tr": ["pazarlık yapmak"], "example_en": "You can bargain at the market.", "example_tr": "Pazarda pazarlık yapabilirsin."}]}, {"id": "b1-discount", "word": "discount", "pos": "n", "level": "B1", "tr": ["indirim"], "example_en": "Is there a discount for students?", "example_tr": "Öğrenciler için indirim var mı?"}, {"id": "b1-refund", "word": "refund", "pos": "n", "level": "B1", "tr": ["para iadesi"], "example_en": "I want a refund for this bag.", "example_tr": "Bu çanta için para iadesi istiyorum."}, {"id": "b1-receipt", "word": "receipt", "pos": "n", "level": "B1", "tr": ["fiş", "makbuz"], "example_en": "Do you have the receipt?", "example_tr": "Fişiniz var mı?", "note": "Okunurken ''p'' harfi söylenmez (risit)."}, {"id": "b1-complain", "word": "complain", "pos": "v", "level": "B1", "tr": ["şikâyet etmek"], "example_en": "I want to complain about the food.", "example_tr": "Yemek hakkında şikâyet etmek istiyorum."}, {"id": "b1-complaint", "word": "complaint", "pos": "n", "level": "B1", "tr": ["şikâyet"], "example_en": "I have a complaint about this hotel.", "example_tr": "Bu otel hakkında bir şikâyetim var."}, {"id": "b1-quality", "word": "quality", "pos": "n", "level": "B1", "tr": ["kalite"], "example_en": "The quality of these shoes is bad.", "example_tr": "Bu ayakkabıların kalitesi kötü."}, {"id": "b1-offer", "word": "offer", "pos": "v", "level": "B1", "tr": ["teklif etmek", "sunmak"], "example_en": "They offer a good price.", "example_tr": "İyi bir fiyat sunuyorlar.", "senses": [{"pos": "n", "tr": ["teklif"], "example_en": "That is a great offer.", "example_tr": "Bu harika bir teklif."}]}, {"id": "b1-deliver", "word": "deliver", "pos": "v", "level": "B1", "tr": ["teslim etmek"], "example_en": "Can you deliver it tomorrow?", "example_tr": "Yarın teslim edebilir misiniz?"}, {"id": "b1-delivery", "word": "delivery", "pos": "n", "level": "B1", "tr": ["teslimat"], "example_en": "The delivery is late.", "example_tr": "Teslimat gecikti."}]'::jsonb)
