insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000013', '00000000-0000-4000-8000-00000000c0de', 'Kariyer ve iş görüşmesi', 'public', '[{"id": "b1-apply", "word": "apply", "pos": "v", "level": "B1", "tr": ["başvurmak"], "example_en": "I want to apply for this job.", "example_tr": "Bu işe başvurmak istiyorum."}, {"id": "b1-application", "word": "application", "pos": "n", "level": "B1", "tr": ["başvuru"], "example_en": "Did you send your application?", "example_tr": "Başvurunu gönderdin mi?"}, {"id": "b1-qualification", "word": "qualification", "pos": "n", "level": "B1", "tr": ["nitelik", "vasıf"], "example_en": "What qualifications do you have?", "example_tr": "Ne gibi nitelikleriniz var?"}, {"id": "b1-promotion", "word": "promotion", "pos": "n", "level": "B1", "tr": ["terfi"], "example_en": "She expects a promotion soon.", "example_tr": "Yakında terfi bekliyor."}, {"id": "b1-responsible", "word": "responsible", "pos": "adj", "level": "B1", "tr": ["sorumlu"], "example_en": "He is responsible for the team.", "example_tr": "Takımdan o sorumlu."}, {"id": "b1-achieve", "word": "achieve", "pos": "v", "level": "B1", "tr": ["ulaşmak", "başarmak"], "example_en": "We finally achieved our goal.", "example_tr": "Sonunda hedefimize ulaştık."}, {"id": "b1-succeed", "word": "succeed", "pos": "v", "level": "B1", "tr": ["başarılı olmak"], "example_en": "You can succeed if you try.", "example_tr": "Denersen başarılı olabilirsin."}, {"id": "b1-success", "word": "success", "pos": "n", "level": "B1", "tr": ["başarı"], "example_en": "The new app was a big success.", "example_tr": "Yeni uygulama büyük bir başarıydı."}, {"id": "b1-opportunity", "word": "opportunity", "pos": "n", "level": "B1", "tr": ["fırsat"], "example_en": "This is a great opportunity.", "example_tr": "Bu harika bir fırsat."}, {"id": "b1-challenge", "word": "challenge", "pos": "n", "level": "B1", "tr": ["zorluk", "meydan okuma"], "example_en": "I like a challenge.", "example_tr": "Zorlukları severim."}, {"id": "b1-develop", "word": "develop", "pos": "v", "level": "B1", "tr": ["geliştirmek"], "example_en": "We need to develop new skills.", "example_tr": "Yeni beceriler geliştirmeliyiz."}, {"id": "b1-improve", "word": "improve", "pos": "v", "level": "B1", "tr": ["geliştirmek", "iyileştirmek"], "example_en": "I want to improve my English.", "example_tr": "İngilizcemi geliştirmek istiyorum."}, {"id": "b1-goal", "word": "goal", "pos": "n", "level": "B1", "tr": ["hedef", "amaç"], "example_en": "My first goal is to be a manager.", "example_tr": "İlk hedefim yönetici olmak."}, {"id": "b1-ambition", "word": "ambition", "pos": "n", "level": "B1", "tr": ["hırs", "büyük hedef"], "example_en": "Her ambition is to be the boss.", "example_tr": "Hayali patron olmak."}]'::jsonb)
