insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000014', '00000000-0000-4000-8000-00000000c0de', 'Medya ve sosyal medya', 'public', '[{"id": "b1-article", "word": "article", "pos": "n", "level": "B1", "tr": ["makale", "yazı"], "example_en": "I recently read a good article.", "example_tr": "Geçenlerde iyi bir makale okudum."}, {"id": "b1-journalist", "word": "journalist", "pos": "n", "level": "B1", "tr": ["gazeteci"], "example_en": "The journalist works for a big company.", "example_tr": "Gazeteci büyük bir şirket için çalışıyor."}, {"id": "b1-advertisement", "word": "advertisement", "pos": "n", "level": "B1", "tr": ["reklam"], "example_en": "I saw an advertisement for a new app.", "example_tr": "Yeni bir uygulamanın reklamını gördüm."}, {"id": "b1-post", "word": "post", "pos": "n", "level": "B1", "tr": ["gönderi", "paylaşım"], "example_en": "Did you see her new post?", "example_tr": "Onun yeni gönderisini gördün mü?", "senses": [{"pos": "v", "tr": ["paylaşmak", "yazmak"], "example_en": "I usually post photos online.", "example_tr": "İnternette genelde fotoğraf paylaşırım."}]}, {"id": "b1-comment", "word": "comment", "pos": "n", "level": "B1", "tr": ["yorum"], "example_en": "He left a bad comment.", "example_tr": "Kötü bir yorum bıraktı."}, {"id": "b1-share", "word": "share", "pos": "v", "level": "B1", "tr": ["paylaşmak"], "example_en": "Can you share this photo with me?", "example_tr": "Bu fotoğrafı benimle paylaşabilir misin?"}, {"id": "b1-channel", "word": "channel", "pos": "n", "level": "B1", "tr": ["kanal"], "example_en": "Which channel is the game on?", "example_tr": "Maç hangi kanalda?"}, {"id": "b1-programme", "word": "programme", "pos": "n", "level": "B1", "tr": ["program"], "example_en": "I always watch this programme.", "example_tr": "Bu programı her zaman izlerim."}, {"id": "b1-documentary", "word": "documentary", "pos": "n", "level": "B1", "tr": ["belgesel"], "example_en": "We watched a documentary about animals.", "example_tr": "Hayvanlar hakkında bir belgesel izledik."}, {"id": "b1-accurate", "word": "accurate", "pos": "adj", "level": "B1", "tr": ["doğru", "kesin"], "example_en": "Is this news accurate?", "example_tr": "Bu haber doğru mu?"}, {"id": "b1-fake", "word": "fake", "pos": "adj", "level": "B1", "tr": ["sahte", "yalan"], "example_en": "That is a fake photo.", "example_tr": "O sahte bir fotoğraf."}, {"id": "b1-privacy", "word": "privacy", "pos": "n", "level": "B1", "tr": ["gizlilik"], "example_en": "Privacy is very important online.", "example_tr": "İnternette gizlilik çok önemlidir."}, {"id": "b1-device", "word": "device", "pos": "n", "level": "B1", "tr": ["cihaz", "alet"], "example_en": "You can use this app on any device.", "example_tr": "Bu uygulamayı her cihazda kullanabilirsiniz."}, {"id": "b1-update", "word": "update", "pos": "v", "level": "B1", "tr": ["güncellemek"], "example_en": "You must update the app today.", "example_tr": "Uygulamayı bugün güncellemelisin.", "senses": [{"pos": "n", "tr": ["güncelleme"], "example_en": "There is a new update.", "example_tr": "Yeni bir güncelleme var."}]}]'::jsonb)
