insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000015', '00000000-0000-4000-8000-00000000c0de', 'Çevre', 'public', '[{"id": "b1-environment", "word": "environment", "pos": "n", "level": "B1", "tr": ["çevre"], "example_en": "We must protect the environment.", "example_tr": "Çevreyi korumalıyız."}, {"id": "b1-pollution", "word": "pollution", "pos": "n", "level": "B1", "tr": ["kirlilik"], "example_en": "Pollution is bad for the planet.", "example_tr": "Kirlilik gezegen için kötü."}, {"id": "b1-climate", "word": "climate", "pos": "n", "level": "B1", "tr": ["iklim"], "example_en": "The climate is changing fast.", "example_tr": "İklim hızla değişiyor."}, {"id": "b1-recycle", "word": "recycle", "pos": "v", "level": "B1", "tr": ["geri dönüştürmek"], "example_en": "We should recycle plastic.", "example_tr": "Plastiği geri dönüştürmeliyiz."}, {"id": "b1-protect", "word": "protect", "pos": "v", "level": "B1", "tr": ["korumak"], "example_en": "We need to protect nature.", "example_tr": "Doğayı korumamız gerekiyor."}, {"id": "b1-reduce", "word": "reduce", "pos": "v", "level": "B1", "tr": ["azaltmak"], "example_en": "We must reduce plastic use.", "example_tr": "Plastik kullanımını azaltmalıyız."}, {"id": "b1-energy", "word": "energy", "pos": "n", "level": "B1", "tr": ["enerji"], "example_en": "We use a lot of energy.", "example_tr": "Çok fazla enerji kullanıyoruz."}, {"id": "b1-plastic", "word": "plastic", "pos": "n", "level": "B1", "tr": ["plastik"], "example_en": "Plastic is bad for the planet.", "example_tr": "Plastik gezegen için kötü."}, {"id": "b1-nature", "word": "nature", "pos": "n", "level": "B1", "tr": ["doğa"], "example_en": "I love walking in nature.", "example_tr": "Doğada yürüyüş yapmayı severim."}, {"id": "b1-wildlife", "word": "wildlife", "pos": "n", "level": "B1", "tr": ["yaban hayatı"], "example_en": "Pollution is destroying wildlife.", "example_tr": "Kirlilik yaban hayatını yok ediyor."}, {"id": "b1-global", "word": "global", "pos": "adj", "level": "B1", "tr": ["küresel"], "example_en": "Pollution is a global problem.", "example_tr": "Kirlilik küresel bir sorun."}, {"id": "b1-destroy", "word": "destroy", "pos": "v", "level": "B1", "tr": ["yok etmek", "yıkmak"], "example_en": "Storms destroy houses.", "example_tr": "Fırtınalar evleri yıkıyor."}, {"id": "b1-damage", "word": "damage", "pos": "v", "level": "B1", "tr": ["zarar vermek"], "example_en": "Earthquakes damage cities.", "example_tr": "Depremler şehirlere zarar verir.", "senses": [{"pos": "n", "tr": ["hasar", "zarar"], "example_en": "The storm caused a lot of damage.", "example_tr": "Fırtına büyük hasara neden oldu."}]}, {"id": "b1-flood", "word": "flood", "pos": "n", "level": "B1", "tr": ["sel"], "example_en": "The rain caused a big flood.", "example_tr": "Yağmur büyük bir sele neden oldu."}]'::jsonb)
on conflict (id) do update set title = excluded.title, visibility = excluded.visibility, cards = excluded.cards;

insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000016', '00000000-0000-4000-8000-00000000c0de', 'İş İngilizcesi', 'public', '[{"id": "b2-negotiate", "word": "negotiate", "pos": "v", "level": "B2", "tr": ["pazarlık etmek", "görüşmek"], "example_en": "We must negotiate the price with the company.", "example_tr": "Şirketle fiyat konusunda pazarlık yapmalıyız."}, {"id": "b2-client", "word": "client", "pos": "n", "level": "B2", "tr": ["müşteri", "müvekkil"], "example_en": "The new client wants an important meeting.", "example_tr": "Yeni müşteri önemli bir toplantı istiyor."}, {"id": "b2-profit", "word": "profit", "pos": "n", "level": "B2", "tr": ["kâr", "kazanç"], "example_en": "Our company made a significant profit this year.", "example_tr": "Şirketimiz bu yıl önemli bir kâr elde etti."}, {"id": "b2-invest", "word": "invest", "pos": "v", "level": "B2", "tr": ["yatırım yapmak"], "example_en": "We should invest in new computers.", "example_tr": "Yeni bilgisayarlara yatırım yapmalıyız."}, {"id": "b2-investment", "word": "investment", "pos": "n", "level": "B2", "tr": ["yatırım"], "example_en": "This is a reasonable investment for our future.", "example_tr": "Bu, geleceğimiz için makul bir yatırım."}, {"id": "b2-competitor", "word": "competitor", "pos": "n", "level": "B2", "tr": ["rakip"], "example_en": "Our biggest competitor is launching a new app.", "example_tr": "En büyük rakibimiz yeni bir uygulama başlatıyor."}, {"id": "b2-strategy", "word": "strategy", "pos": "n", "level": "B2", "tr": ["strateji"], "example_en": "We need to change our strategy now.", "example_tr": "Stratejimizi şimdi değiştirmeliyiz."}, {"id": "b2-priority", "word": "priority", "pos": "n", "level": "B2", "tr": ["öncelik"], "example_en": "Our first priority is to make the client happy.", "example_tr": "İlk önceliğimiz müşteriyi mutlu etmektir."}, {"id": "b2-establish", "word": "establish", "pos": "v", "level": "B2", "tr": ["kurmak", "tesis etmek"], "example_en": "We will establish a new office in London.", "example_tr": "Londra''da yeni bir ofis kuracağız."}, {"id": "b2-maintain", "word": "maintain", "pos": "v", "level": "B2", "tr": ["sürdürmek", "korumak"], "example_en": "We must maintain a good relationship with them.", "example_tr": "Onlarla iyi bir ilişki sürdürmeliyiz."}, {"id": "b2-enhance", "word": "enhance", "pos": "v", "level": "B2", "tr": ["geliştirmek", "artırmak"], "example_en": "This update will enhance the app''s efficiency.", "example_tr": "Bu güncelleme uygulamanın verimliliğini artıracak."}, {"id": "b2-delegate", "word": "delegate", "pos": "v", "level": "B2", "tr": ["görev vermek", "devretmek"], "example_en": "A good manager must delegate work to the team.", "example_tr": "İyi bir yönetici işleri ekibe devretmelidir."}, {"id": "b2-proposal", "word": "proposal", "pos": "n", "level": "B2", "tr": ["teklif", "öneri"], "example_en": "I will read your proposal tomorrow morning.", "example_tr": "Teklifinizi yarın sabah okuyacağım."}, {"id": "b2-objective", "word": "objective", "pos": "n", "level": "B2", "tr": ["hedef", "amaç"], "example_en": "Our first objective is to expand the company.", "example_tr": "İlk hedefimiz şirketi büyütmektir."}]'::jsonb)
