insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000017', '00000000-0000-4000-8000-00000000c0de', 'Akademik İngilizce', 'public', '[{"id": "b2-academic", "word": "academic", "pos": "adj", "level": "B2", "tr": ["akademik"], "example_en": "She has a great academic career.", "example_tr": "Harika bir akademik kariyeri var."}, {"id": "b2-thesis", "word": "thesis", "pos": "n", "level": "B2", "tr": ["tez"], "example_en": "I must finish my thesis soon.", "example_tr": "Tezimi yakında bitirmeliyim."}, {"id": "b2-lecture", "word": "lecture", "pos": "n", "level": "B2", "tr": ["ders", "konferans"], "example_en": "The lecture was very long.", "example_tr": "Ders çok uzundu."}, {"id": "b2-seminar", "word": "seminar", "pos": "n", "level": "B2", "tr": ["seminer"], "example_en": "I will attend a seminar today.", "example_tr": "Bugün bir seminere katılacağım."}, {"id": "b2-scholarship", "word": "scholarship", "pos": "n", "level": "B2", "tr": ["burs"], "example_en": "Did you get a scholarship?", "example_tr": "Burs aldın mı?"}, {"id": "b2-curriculum", "word": "curriculum", "pos": "n", "level": "B2", "tr": ["müfredat"], "example_en": "The new curriculum is difficult.", "example_tr": "Yeni müfredat zor."}, {"id": "b2-assessment", "word": "assessment", "pos": "n", "level": "B2", "tr": ["değerlendirme"], "example_en": "The assessment was hard.", "example_tr": "Değerlendirme zordu."}, {"id": "b2-essay", "word": "essay", "pos": "n", "level": "B2", "tr": ["kompozisyon", "deneme"], "example_en": "My essay is almost ready.", "example_tr": "Makalem neredeyse hazır."}, {"id": "b2-tuition", "word": "tuition", "pos": "n", "level": "B2", "tr": ["okul ücreti", "harç"], "example_en": "Tuition is expensive here.", "example_tr": "Burada okul ücreti pahalı."}, {"id": "b2-discipline", "word": "discipline", "pos": "n", "level": "B2", "tr": ["disiplin"], "example_en": "You need discipline to succeed.", "example_tr": "Başarmak için disipline ihtiyacın var."}, {"id": "b2-concept", "word": "concept", "pos": "n", "level": "B2", "tr": ["kavram", "konsept"], "example_en": "This is a difficult concept.", "example_tr": "Bu zor bir kavram."}, {"id": "b2-summarize", "word": "summarize", "pos": "v", "level": "B2", "tr": ["özetlemek"], "example_en": "Can you summarize the story?", "example_tr": "Hikayeyi özetleyebilir misin?"}, {"id": "b2-critical", "word": "critical", "pos": "adj", "level": "B2", "tr": ["eleştirel", "kritik"], "example_en": "It is a critical decision.", "example_tr": "Bu kritik bir karar."}, {"id": "b2-evaluate", "word": "evaluate", "pos": "v", "level": "B2", "tr": ["değerlendirmek"], "example_en": "We must evaluate the results.", "example_tr": "Sonuçları değerlendirmeliyiz."}]'::jsonb)
