insert into public.lists (id, owner, title, visibility, cards) values ('a1b2c3d4-0000-4000-8000-000000000018', '00000000-0000-4000-8000-00000000c0de', 'Ekonomi haberleri', 'public', '[{"id": "b2-economy", "word": "economy", "pos": "n", "level": "B2", "tr": ["ekonomi"], "example_en": "The global economy is growing.", "example_tr": "Küresel ekonomi büyüyor."}, {"id": "b2-inflation", "word": "inflation", "pos": "n", "level": "B2", "tr": ["enflasyon"], "example_en": "Inflation reduces our income.", "example_tr": "Enflasyon gelirimizi azaltıyor."}, {"id": "b2-income", "word": "income", "pos": "n", "level": "B2", "tr": ["gelir"], "example_en": "My income is quite small.", "example_tr": "Gelirim oldukça az."}, {"id": "b2-tax", "word": "tax", "pos": "n", "level": "B2", "tr": ["vergi"], "example_en": "We have to pay a lot of tax.", "example_tr": "Çok fazla vergi ödemeliyiz."}, {"id": "b2-wage", "word": "wage", "pos": "n", "level": "B2", "tr": ["maaş", "ücret"], "example_en": "I want a better wage.", "example_tr": "Daha iyi bir maaş istiyorum.", "note": "Genellikle haftalık veya saatlik ödenen ücretler için kullanılır."}, {"id": "b2-consumer", "word": "consumer", "pos": "n", "level": "B2", "tr": ["tüketici"], "example_en": "A clever consumer compares prices.", "example_tr": "Akıllı bir tüketici fiyatları karşılaştırır."}, {"id": "b2-demand", "word": "demand", "pos": "n", "level": "B2", "tr": ["talep"], "example_en": "There is a big demand for this car.", "example_tr": "Bu arabaya büyük bir talep var.", "senses": [{"pos": "v", "tr": ["talep etmek"], "example_en": "People demand better wages.", "example_tr": "İnsanlar daha iyi maaşlar talep ediyor."}]}, {"id": "b2-supply", "word": "supply", "pos": "n", "level": "B2", "tr": ["arz", "tedarik"], "example_en": "The supply of cheap food is small.", "example_tr": "Ucuz gıda arzı az."}, {"id": "b2-crisis", "word": "crisis", "pos": "n", "level": "B2", "tr": ["kriz"], "example_en": "The financial crisis destroyed many jobs.", "example_tr": "Finansal kriz birçok işi yok etti."}, {"id": "b2-recession", "word": "recession", "pos": "n", "level": "B2", "tr": ["resesyon", "durgunluk"], "example_en": "The economy is in a bad recession.", "example_tr": "Ekonomi kötü bir durgunluk içinde."}, {"id": "b2-purchase", "word": "purchase", "pos": "v", "level": "B2", "tr": ["satın almak"], "example_en": "I want to purchase a new laptop.", "example_tr": "Yeni bir dizüstü bilgisayar satın almak istiyorum.", "senses": [{"pos": "n", "tr": ["satın alma"], "example_en": "Is it a reasonable purchase?", "example_tr": "Bu makul bir satın alma mı?"}]}, {"id": "b2-brand", "word": "brand", "pos": "n", "level": "B2", "tr": ["marka"], "example_en": "It is a famous brand.", "example_tr": "Bu ünlü bir marka."}, {"id": "b2-subscription", "word": "subscription", "pos": "n", "level": "B2", "tr": ["abonelik"], "example_en": "I cancelled my app subscription.", "example_tr": "Uygulama aboneliğimi iptal ettim."}, {"id": "b2-wealth", "word": "wealth", "pos": "n", "level": "B2", "tr": ["servet", "zenginlik"], "example_en": "His family has a lot of wealth.", "example_tr": "Ailesinin büyük bir serveti var."}]'::jsonb)
