level": "C1", "tr": ["manipüle etmek", "yönlendirmek"], "example_en": "Scientists can manipulate genes in the lab.", "example_tr": "Bilim insanları laboratuvarda genlerle oynayabilir."}, {"id": "b2-evidence", "word": "evidence", "pos": "n", "level": "B2", "tr": ["kanıt"], "example_en": "We need genuine evidence.", "example_tr": "Gerçek bir kanıta ihtiyacımız var."}, {"id": "exam-trace", "word": "trace", "pos": "n", "level": "B2", "tr": ["iz", "kalıntı"], "example_en": "There is no trace of poison.", "example_tr": "Zehir izi yok."}, {"id": "c1-controversial", "word": "controversial", "pos": "adj", "level": "C1", "tr": ["tartışmalı"], "example_en": "This is a very controversial issue.", "example_tr": "Bu çok tartışmalı bir mesele."}, {"id": "b2-concern", "word": "concern", "pos": "n", "level": "B2", "tr": ["endişe"], "example_en": "The price is a big concern.", "example_tr": "Fiyat büyük bir endişe."}, {"id": "b2-policy", "word": "policy", "pos": "n", "level": "B2", "tr": ["politika", "kural"], "example_en": "The new policy will reduce unemployment.", "example_tr": "Yeni politika işsizliği azaltacak.", "note": "''politics'' genel siyaset, ''policy'' ise izlenen yoldur."}, {"id": "exam-therapeutic", "word": "therapeutic", "pos": "adj", "level": "C1", "tr": ["tedavi edici"], "example_en": "Music can have a therapeutic effect on stress.", "example_tr": "Müziğin stres üzerinde tedavi edici etkisi olabilir."}]'::jsonb)
